using System.Runtime.InteropServices;using SDL3;namespace FlareEngine.Sdl;/// <summary>///     将 SDL3 原生事件映射为引擎沿用的 SDL2 事件编号语义，///     供 <see cref="SDLInputState.Handle" /> 中的 switch 分支直接消费。///     分支与 C++ <c>SDLInputState::handle()</c> 处理的 <c>event.type</c> 一一对应。/// </summary>internal static class Sdl3EventMapper{    public static bool TryMap(SDL.Event source, out SdlPollEvent target)    {        target = default;        switch ((SDL.EventType)source.Type)        {            // SDL_QUIT            case SDL.EventType.Quit:                target.Type = SdlInputEventType.Quit;                return true;            // SDL_TEXTINPUT — inkeys += event.text.text            case SDL.EventType.TextInput:                target.Type = SdlInputEventType.TextInput;                target.TextInput = new SdlTextInputEventData                {                    Text = Marshal.PtrToStringUTF8(source.Text.Text) ?? string.Empty                };                return true;            // SDL_KEYDOWN — binding[key].bind == event.key.keysym.scancode            case SDL.EventType.KeyDown:                target.Type = SdlInputEventType.KeyDown;                target.Key = new SdlKeyboardEvent                {                    Keysym = new SdlKeysym                    {                        Scancode = (int)source.Key.Scancode,                        Sym = (int)source.Key.Key,                        Mod = (ushort)source.Key.Mod                    },                    State = SdlEventCodes.Pressed                };                return true;            // SDL_KEYUP            case SDL.EventType.KeyUp:                target.Type = SdlInputEventType.KeyUp;                target.Key = new SdlKeyboardEvent                {                    Keysym = new SdlKeysym                    {                        Scancode = (int)source.Key.Scancode,                        Sym = (int)source.Key.Key,                        Mod = (ushort)source.Key.Mod                    },                    State = SdlEventCodes.Released                };                return true;            // SDL_MOUSEMOTION — scaleMouse(event.motion.x, event.motion.y)            case SDL.EventType.MouseMotion:                target.Type = SdlInputEventType.MouseMotion;                target.Motion = new SdlMouseMotionEvent                {                    X = (int)source.Motion.X,                    Y = (int)source.Motion.Y,                    XRel = (int)source.Motion.XRel,                    YRel = (int)source.Motion.YRel,                    State = (uint)source.Motion.State                };                return true;            // SDL_MOUSEBUTTONDOWN — event.button.button 与 SDL_BUTTON_LEFT(1) 等直接比较            case SDL.EventType.MouseButtonDown:                target.Type = SdlInputEventType.MouseButtonDown;                target.Button = new SdlMouseButtonEvent                {                    Button = source.Button.Button,                    X = (int)source.Button.X,                    Y = (int)source.Button.Y,                    State = 1                };                return true;            // SDL_MOUSEBUTTONUP            case SDL.EventType.MouseButtonUp:                target.Type = SdlInputEventType.MouseButtonUp;                target.Button = new SdlMouseButtonEvent                {                    Button = source.Button.Button,                    X = (int)source.Button.X,                    Y = (int)source.Button.Y,                    State = 0                };                return true;            // SDL_MOUSEWHEEL — event.wheel.y &gt; 0 / &lt; 0            case SDL.EventType.MouseWheel:                target.Type = SdlInputEventType.MouseWheel;                target.Wheel = new SdlMouseWheelEventData { Y = (int)source.Wheel.Y };                return true;            // SDL_WINDOWEVENT — SDL_WINDOWEVENT_SIZE_CHANGED / MINIMIZED / ...            case SDL.EventType.WindowPixelSizeChanged:            case SDL.EventType.WindowResized:                target.Type = SdlInputEventType.WindowEvent;                target.Window = new SdlWindowEventData { Event = SdlWindowEventId.SizeChanged };                return true;            case SDL.EventType.WindowMinimized:                target.Type = SdlInputEventType.WindowEvent;                target.Window = new SdlWindowEventData { Event = SdlWindowEventId.Minimized };                return true;            case SDL.EventType.WindowRestored:                target.Type = SdlInputEventType.WindowEvent;                target.Window = new SdlWindowEventData { Event = SdlWindowEventId.Restored };                return true;            case SDL.EventType.WindowFocusLost:                target.Type = SdlInputEventType.WindowEvent;                target.Window = new SdlWindowEventData { Event = SdlWindowEventId.FocusLost };                return true;            case SDL.EventType.WindowFocusGained:                target.Type = SdlInputEventType.WindowEvent;                target.Window = new SdlWindowEventData { Event = SdlWindowEventId.FocusGained };                return true;            // SDL_CONTROLLERAXISMOTION — joy_id == event.caxis.which            case SDL.EventType.GamepadAxisMotion:                target.Type = SdlInputEventType.ControllerAxisMotion;                target.CAxis = new SdlControllerAxisEventData                {                    Which = (int)source.GAxis.Which,                    Axis = source.GAxis.Axis,                    Value = source.GAxis.Value                };                return true;            // SDL_CONTROLLERBUTTONDOWN — bind == event.cbutton.button            case SDL.EventType.GamepadButtonDown:                target.Type = SdlInputEventType.ControllerButtonDown;                target.CButton = new SdlControllerButtonEventData                {                    Which = (int)source.GButton.Which,                    Button = source.GButton.Button                };                return true;            case SDL.EventType.GamepadButtonUp:                target.Type = SdlInputEventType.ControllerButtonUp;                target.CButton = new SdlControllerButtonEventData                {                    Which = (int)source.GButton.Which,                    Button = source.GButton.Button                };                return true;            // SDL_JOYDEVICEADDED / SDL_JOYDEVICEREMOVED            case SDL.EventType.JoystickAdded:                target.Type = SdlInputEventType.JoyDeviceAdded;                target.JDevice = new SdlJoyDeviceEventData { Which = (int)source.JDevice.Which };                return true;            case SDL.EventType.JoystickRemoved:                target.Type = SdlInputEventType.JoyDeviceRemoved;                target.JDevice = new SdlJoyDeviceEventData { Which = (int)source.JDevice.Which };                return true;            // SDL_FINGERDOWN / SDL_FINGERMOTION / SDL_FINGERUP            case SDL.EventType.FingerDown:                target.Type = SdlInputEventType.FingerDown;                target.TFinger = MapFinger(source.TFinger);                return true;            case SDL.EventType.FingerUp:                target.Type = SdlInputEventType.FingerUp;                target.TFinger = MapFinger(source.TFinger);                return true;            case SDL.EventType.FingerMotion:                target.Type = SdlInputEventType.FingerMotion;                target.TFinger = MapFinger(source.TFinger);                return true;            default:                return false;        }    }    private static SdlTouchFingerEventData MapFinger(SDL.TouchFingerEvent finger)    {        return new SdlTouchFingerEventData        {            FingerId = (long)finger.FingerID,            X = finger.X,            Y = finger.Y,            Dx = finger.DX,            Dy = finger.DY        };    }}